class Component extends DCLogic {
  state = { tab: 'all', sel: 1, unread: Object.fromEntries(MSGS.map((m) => [m.id, m.unread])) }
  componentDidMount() {
    this.read(1)
  }
  read(id) {
    this.setState((s) => ({ sel: id, unread: { ...s.unread, [id]: false } }))
  }
  renderVals() {
    const S = this.state
    const unreadCount = MSGS.filter((m) => S.unread[m.id]).length
    const list = MSGS.filter((m) => S.tab === 'all' || (S.tab === 'unread' ? S.unread[m.id] : m.kind !== 'all'))
    const groups = ['Today', 'Earlier']
      .map((day) => ({
        label: day,
        items: list
          .filter((m) => m.day === day)
          .map((m) => {
            const on = S.sel === m.id,
              un = S.unread[m.id]
            return {
              ...m,
              open: () => this.read(m.id),
              bg: on ? 'rgba(255,255,255,.05)' : 'transparent',
              weight: un ? 600 : 500,
              titleFg: un ? '#f7f8f8' : '#d4d6da',
              dotOp: un ? 1 : 0,
              dotScale: un ? 1 : 0.4,
            }
          }),
      }))
      .filter((g) => g.items.length)
    const sel = MSGS.find((m) => m.id === S.sel)
    const tab = (key, label, count) => ({
      label,
      count,
      bg: S.tab === key ? 'rgba(255,255,255,.06)' : 'transparent',
      fg: S.tab === key ? '#f7f8f8' : '#8a8f98',
      pick: () => this.setState({ tab: key }),
    })
    return {
      tabs: [
        tab('all', 'All', MSGS.length),
        tab('unread', 'Unread', unreadCount),
        tab('providers', 'Providers', MSGS.filter((m) => m.kind !== 'all').length),
      ],
      groups,
      listEmpty: groups.length === 0,
      markAll: () => this.setState({ unread: Object.fromEntries(MSGS.map((m) => [m.id, false])) }),
      hasSel: !!sel,
      noSel: !sel,
      sel: sel ? { ...sel, hasFacts: true, facts: sel.facts.map(([k, v]) => ({ k, v })) } : { facts: [] },
      readLabel: sel && S.unread[sel.id] ? 'Mark as read' : 'Mark as unread',
      toggleRead: () => sel && this.setState((s) => ({ unread: { ...s.unread, [sel.id]: !s.unread[sel.id] } })),
    }
  }
}

{
  const designVals = Component.prototype.renderVals
  const appVals = function (v) {
    return {
      appViewProvider: () => {
        const p = RELAY.providers.find((x) => x.name === v.sel?.from)
        if (p) this.props.onOpenProvider?.(p.id, 'inbox')
      },
    }
  }
  Component.prototype.renderVals = function () {
    const v = designVals.call(this)
    return { ...v, ...appVals.call(this, v) }
  }
}

